const item = $input.item.json;
const result = item.step1_result;

// Notion 블록 형식으로 변환
const blocks = [
  {
    "object": "block",
    "type": "heading_2",
    "heading_2": {
      "rich_text": [{ "type": "text", "text": { "content": "🎯 1단계: 서브토픽 분석" } }]
    }
  }
];

if (result.subtopics && Array.isArray(result.subtopics)) {
  result.subtopics.forEach((topic, index) => {
    blocks.push({
      "object": "block",
      "type": "heading_3",
      "heading_3": {
        "rich_text": [{ "type": "text", "text": { "content": `${index + 1}. ${topic.name}` } }]
      }
    });

    blocks.push({
      "object": "block",
      "type": "paragraph",
      "paragraph": {
        "rich_text": [{ 
          "type": "text", 
          "text": { "content": `시간: ${topic.duration}분\n설명: ${topic.description}` } 
        }]
      }
    });
  });

  blocks.push({
    "object": "block",
    "type": "paragraph",
    "paragraph": {
      "rich_text": [{ 
        "type": "text", 
        "text": { "content": `\n총 예상 시간: ${result.total_duration}분\n통과 여부: ${result.pass ? '✅ 통과' : '❌ 보완 필요'}\n평가: ${result.reason}` } 
      }]
    }
  });
}

return {
  ...item,
  notion_blocks: blocks
};

const item = $input.item.json;
const result = item.step2_result;

// Notion 블록 형식으로 변환
const blocks = [
