    "object": "block",
    "type": "paragraph",
    "paragraph": {
      "rich_text": [{ "type": "text", "text": { "content": result.debates.join('\n\n') } }]
    }
  });
}

if (result.tips && Array.isArray(result.tips)) {
  blocks.push({
    "object": "block",
    "type": "heading_3",
    "heading_3": {
      "rich_text": [{ "type": "text", "text": { "content": "팁 (Tips)" } }]
    }
