    }
  });
}

return {
  ...item,
  notion_blocks_step2: blocks
};

// 이전 단계의 데이터 가져오기
const previousData = $('2단계 결과 파싱1').item.json;

// 1단계와 2단계 결과 확인
const step1Result = previousData.step1_result || {};
const step2Result = previousData.step2_result || {};
const topic = previousData.topic || '제목 없음';
const pageId = previousData.page_id || '';

// 3단계 프롬프트 생성
const prompt = `다음 팟캐스트 주제와 분석 결과를 바탕으로 대본 구조를 만들어주세요.

주제: ${topic}

1단계 결과 (서브토픽):
${JSON.stringify(step1Result, null, 2)}

2단계 결과 (소재 발굴):
${JSON.stringify(step2Result, null, 2)}

다음 형식으로 대본 구조를 만들어주세요:
- 각 세그먼트는 제목, 시간, 논의 포인트를 포함
- 세그먼트 간 자연스러운 전환 문구 추가
- 총 50분 이상의 대본 구조

출력 형식 (반드시 JSON으로만 응답):
{
  "segments": [
    {
      "title": "세그먼트 제목",
      "duration": 10,
      "discussion_points": ["포인트1", "포인트2"],
      "transition": "다음 세그먼트로의 전환 문구"
    }
  ],
  "total_duration": 55
}`;

// Claude API 요청 본문 생성
const claudeRequestBody = {
  "model": "claude-3-5-sonnet-20241022",
  "max_tokens": 4096,
  "messages": [
    {
      "role": "user",
      "content": prompt
    }
  ]
};

// 이전 데이터와 함께 반환
return {
  ...previousData,
  claudeRequestBody: claudeRequestBody,
  prompt_step3: prompt
};

const item = $input.item.json;
const result = item.step3_result;

// Notion 블록 형식으로 변환
const blocks = [
  {
    "object": "block",
    "type": "heading_2",
    "heading_2": {
      "rich_text": [{ "type": "text", "text": { "content": "📝 3단계: 대본 구조" } }]
    }
  }
];

if (result.segments && Array.isArray(result.segments)) {
  result.segments.forEach((segment, index) => {
    blocks.push({
      "object": "block",
      "type": "heading_3",
      "heading_3": {
        "rich_text": [{ "type": "text", "text": { "content": `${index + 1}. ${segment.title} (${segment.duration}분)` } }]
      }
    });

    if (segment.discussion_points && Array.isArray(segment.discussion_points)) {
      blocks.push({
        "object": "block",
        "type": "paragraph",
        "paragraph": {
          "rich_text": [{ 
            "type": "text", 
            "text": { "content": `논의 포인트:\n${segment.discussion_points.map(p => `• ${p}`).join('\n')}` } 
          }]
        }
      });
    }

    if (segment.transition) {
      blocks.push({
        "object": "block",
        "type": "paragraph",
        "paragraph": {
          "rich_text": [{ 
            "type": "text", 
            "text": { "content": `전환: ${segment.transition}` } 
          }]
        }
      });
    }
  });
}

return {
  ...item,
  notion_blocks_step3: blocks
};

// 노션 자동화 웹훅에서 받은 데이터 파싱
const webhookData = $input.item.json;

// body.data 안에 실제 페이지 정보가 있음
const pageData = webhookData.body?.data || webhookData.data || webhookData;

const pageId = pageData.id || '';
const pageName = pageData.properties?.Name?.title?.[0]?.plain_text || '제목 없음';

// 로깅용 (디버깅)
console.log('페이지 ID:', pageId);
console.log('페이지 이름:', pageName);

// 페이지 ID가 없으면 에러 발생
if (!pageId) {
  throw new Error('페이지 ID를 찾을 수 없습니다. 웹훅 데이터를 확인해주세요.');
}

return {
  page_id: pageId,
  topic: pageName,
  webhook_raw: pageData
};

const response = $input.item.json;

const content = response.choices?.[0]?.message?.content || '';

if (!content) {
  return { 
    step1_result: { error: '응답 없음' }, 
    step1_raw: '',
    page_id: $('변수 설정1').item.json.page_id,
    topic: $('변수 설정1').item.json.topic
  };
}

let result;
try {
  // Try to extract JSON from markdown code block first
  const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/);
  if (jsonMatch) {
    result = JSON.parse(jsonMatch[1].trim());
  } else {
    // Fallback to old method for responses without markdown
    const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    result = JSON.parse(cleaned);
  }
} catch (e) {
  return { 
    step1_result: { error: 'JSON 파싱 실패', raw: content },
    step1_raw: content,
    page_id: $('변수 설정1').item.json.page_id,
    topic: $('변수 설정1').item.json.topic
  };
}

return {
  step1_result: result,
  step1_raw: content,
  page_id: $('변수 설정1').item.json.page_id,
  topic: $('변수 설정1').item.json.topic
};

